$(document).ready(function(){$("#searchUser").click(function(e){e.preventDefault;var o=$("#mobile").val();return o.length<10||$.ajax({type:"GET",url:"/api/user/search?type=mobile&value="+o,dataType:"json",success:function(e){console.log(e),$("#searchByMobile").hide()},error:function(e){console.log("Error"),console.log(e)}}),!1})});